\set ON_ERROR_STOP on
BEGIN;
CREATE SCHEMA auth;
CREATE SCHEMA private;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE auth.mfa_factors(id uuid PRIMARY KEY,user_id uuid,status text);
DO $$ BEGIN CREATE ROLE anon; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role BYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticator; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb) $$;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(auth.jwt()->>'sub','')::uuid $$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION auth.uid(),auth.jwt() TO anon,authenticated,service_role;
INSERT INTO auth.users VALUES('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222'),('33333333-3333-4333-8333-333333333333');
CREATE TABLE public.profiles(id uuid PRIMARY KEY,account_type text);
INSERT INTO public.profiles VALUES('11111111-1111-4111-8111-111111111111','player'),('22222222-2222-4222-8222-222222222222','fan');
GRANT SELECT ON public.profiles TO authenticated;
CREATE TABLE public.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE,plan text,status text,current_period_end timestamptz,access_status text,billing_interval text DEFAULT 'month',cancel_at_period_end boolean DEFAULT false,stripe_subscription_id text);
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_subscription ON public.subscriptions FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
GRANT SELECT ON public.subscriptions TO anon,authenticated;
GRANT USAGE ON SCHEMA private TO anon,authenticated;
CREATE FUNCTION private.is_active_subscriber() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=(SELECT auth.uid()) AND status IN ('active','trialing') AND (current_period_end IS NULL OR current_period_end>now())) $$;
CREATE FUNCTION public.can_use_unified_hoopfeed() RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p JOIN public.subscriptions s ON s.user_id=p.id WHERE p.id=(SELECT auth.uid()) AND p.account_type IN ('player','fan') AND s.plan IN ('pro','premium') AND s.status IN ('active','trialing') AND coalesce(s.access_status,'active') IN ('active','trialing','pro','premium') AND (s.current_period_end IS NULL OR s.current_period_end>now())) $$;
CREATE TABLE public.reviews(id integer,author_id uuid);
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.reviews TO authenticated;
CREATE POLICY reviews_subscriber_read ON public.reviews FOR SELECT TO authenticated USING(author_id=(SELECT auth.uid()) AND EXISTS(SELECT 1 FROM public.subscriptions s WHERE s.user_id=(SELECT auth.uid()) AND s.plan='premium' AND s.status IN ('active','trialing')));
